'use strict';
function safeDestination(value){try{const url=new URL(value,location.origin);if(url.pathname==='/')url.pathname='/index.html';return url.origin===location.origin&&url.pathname!=='/login.html'&&!url.pathname.startsWith('/api/')?url.pathname+url.search+url.hash:'/index.html';}catch{return '/index.html';}}
const originalDestination=location.pathname!=='/login.html'?location.pathname+location.search+location.hash:new URLSearchParams(location.search).get('return')||'/index.html';
const returnTo=safeDestination(originalDestination);
if(location.pathname!=='/login.html')history.replaceState(null,'','/login.html?return='+encodeURIComponent(returnTo));
const el=id=>document.getElementById(id);let invitation=new URLSearchParams(location.hash.slice(1)).get('invite');if(invitation){history.replaceState(null,'',location.pathname);el('heading').textContent='Your place on the shelf.';el('intro').textContent='Create a password to accept your invitation.';el('email').closest('p').hidden=true;el('email').required=false;el('repeat-wrap').hidden=false;el('repeat').required=true;el('password').autocomplete='new-password';el('submit').textContent='Create account';}
async function post(path,data){const response=await fetch('/api/library/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-Maha-Upload':'1'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'Please try again.');return result;}
el('login-form').onsubmit=async event=>{event.preventDefault();if(location.protocol!=='https:'){el('message').textContent='Use your secure MAHA address before entering a password.';return;}el('submit').disabled=true;try{if(invitation){if(el('password').value!==el('repeat').value)throw Error('Passwords do not match.');await post('accept-invite',{token:invitation,password:el('password').value});invitation=null;el('message').textContent='Account created. Sign in with the email that received the invitation.';el('login-form').reset();el('email').closest('p').hidden=false;el('email').required=true;el('repeat-wrap').hidden=true;el('repeat').required=false;el('submit').textContent='Sign in';}else{await post('login',{email:el('email').value,password:el('password').value});location.href=returnTo;}}catch(error){el('message').textContent=error.message;}finally{el('submit').disabled=false;}};
el('logout').onclick=async()=>{await post('logout',{});try{sessionStorage.removeItem('maha-account-display');}catch{}location.reload();};fetch('/api/library/session').then(r=>r.json()).then(session=>{if(!session.enabled){el('message').textContent='Accounts are not enabled yet.';el('login-form').hidden=true;return;}if(location.protocol!=='https:'){el('login-form').hidden=true;el('message').textContent='Connect to your private VPN, then open the secure library address.';if(session.secureUrl){el('secure-link').hidden=false;el('secure-link').href=session.secureUrl;}}else if(session.user&&!invitation){el('login-form').hidden=true;el('account').hidden=false;el('account').querySelector('a').href=returnTo;el('intro').textContent='Signed in as '+session.user.email;}}).catch(()=>{el('message').textContent='The library could not be reached.';});
